    def findTheLongestBalancedSubstring(self, s):
        """
        :type s: str
        :rtype: int
        """
        ans = 0
        n = len(s)
        cnt = [0, 0]
        for i in range(n):
            if s[i] == '1':
                cnt[1] += 1
                ans = max(ans, 2 * min(cnt))
